//! Cart pump main board v1 (feature `board-cart-v1`, TEST PROJECT, bench only, water only): the cup pod v4 chip set (HJ-840, 2 x DRV8838,
//! STM32C011 supervisor, TPL5010 latch) on the 57.0 x 10.6 mm cart outline. Same nets, same interlock, other HJ-840 GPIO pads.
//! GENERATED by `electronics/v010/cart/sync_firmware_pins_cart.py` from `cup_v4.rs` and `electronics/v010/cart/pin_assign.json`: edit those.
//!
//! Cart differences: `DOCK_N` comes from the ADAPTER-LOCK hall on a pigtail (low = adapter locked, the cup's "docked"); an open pigtail
//! reads high (100 k pull-up RDK) = not locked. Netlist: `electronics/v010/cart/netlist_cart.json`.
//!
//!
//! Pad / nRF pin of the cart hand placement (`electronics/v010/cart/pin_assign.json`; row A, B2-B7 and P0.00 / P0.01 unused):
//!
//! | HJ-840 pad | nRF pin | Net | Use |
//! |---|---|---|---|
//! | D7  | P1.13 | `APHASE`   | out: U7A DRV8838 PH, also supervisor input (PA) |
//! | G4  | P1.09 | `BPHASE`   | out: U7B DRV8838 PH, also supervisor input |
//! | C7  | P1.11 | `AENBL`    | out: bridge A enable, 100 k pull-down: 1 = driven, 0 = brake |
//! | G7  | P0.26 | `BENBL`    | out: bridge B enable |
//! | G8  | P0.06 | `CHG_STAT` | in: MCP73832 STAT, low = charging (high / high-Z otherwise: use `USBDETECTED` for the cable) |
//! | F4  | P0.07 | `OC_OK`    | in: TPS2553 FAULT, low = current limit active (100 k pull-up) |
//! | C8  | P1.12 | `LATCH_Q`  | in: interlock latch readback (RB6) |
//! | D8  | P0.31 | `DOCK_N`   | in: adapter-lock hall DRV5032FA (pigtail), LOW = adapter locked |
//! | E7  | P0.28 | `SUP_OK`   | in: supervisor healthy |
//! | B1  | P0.22 | `LED_R`    | out, active low (RGB common anode on VBAT, 1 k) |
//! | D1  | P0.19 | `LED_G`    | out, active low |
//! | D2  | P1.00 | `LED_B`    | out, active low |
//! | G5  | P0.05 | `SUP_TXD`  | in: UART RX from the supervisor |
//! | F5  | P0.27 | `SUP_RXD`  | out: UART TX to the supervisor |
//! | E2  | P0.15 | `SUP_BOOT0` | out: supervisor BOOT0 strap (100 k pull-down) |
//! | G3  | P0.12 | `SUP_NRST` | io, OPEN DRAIN ONLY (never push-pull high): pulls the supervisor NRST low |
//! | F8  | P0.29 | `MOT_FWD`  | out: forward intent, HIGH = forward (pull-up: reset default = forward = blocked when undocked) |
//! | C1  | P0.25 | `BTN_N`    | in: side button, internal pull-up |
//! | H5  | P0.08 | `I2C_SCL`  | TWIM: TMAG5273 (rear strip), 4.7 k pull-ups, 100 kHz |
//! | F3  | P0.11 | `I2C_SDA`  | TWIM |
//! | F7  | P0.30 | `ARM_CLK`  | out: rising edge sets the latch and arms the supervisor, 100 k pull-down |
//! | E8  | P0.03 | `MCU_EN`   | out: hardware leg of the motor enable (3-input AND `LATCH_Q` & `SUP_PERMIT` & `MCU_EN`), 100 k pull-down |
//! | B8  | P1.14 | `BUZ_A`    | out: sounder NFET gate |
//! | E1  | P0.18 | `NRST`     | reset (UICR PSELRESET), TPL5010 RSTn |
//! | H7  | P0.04 | `VMOT_SENSE` | SAADC AIN2: motor supply after the load switch, 100 k / 100 k (x 2) |
//! | F1/G1/F2 | D+ / D- / VBUS | `USB_DP` / `USB_DM` / `VBUS_P` | USB (DFU, charging); `USBDETECTED` = cable |
//! | C2/C3 | SWDIO / SWCLK | bare pads | one-time bootloader flash |
//! | H2 | VDDH | `VBAT` | the cell: battery voltage through the SAADC `VDDHDIV5` channel (no pin) |
//!
//! Removed against the older boards: no STEP/DIR/STBY/EN-FAULT, no `I_SENSE` (no shunt: occlusion is the angle shortfall only,
//! `OcclusionSource::AngleOnly`), no `OC_TEST`, no `DOCK_TEST`, no `NTC`, no `WDT_*` (the TPL5010 watches the supervisor).
//! The `MOT_FWD` polarity is the OPPOSITE of the older `MOT_DIR` (high = reverse there).
//!
//! Power: HV mode (VDDH = the cell, REG0 supplies the 3V3 rail on the VDD pads): `UICR.REGOUT0` must be 3.3 V ([`regout0_setup`]); the
//! module has no LDO and no 32 kHz crystal (`LfclkSource::InternalRC`).
use embassy_nrf::gpio::AnyPin;
use embassy_nrf::Peri;

pub const BOARD_NAME: &str = "cart-v1";
/// LED pins are active low.
pub const LED_ACTIVE_HIGH: bool = false;
/// The side button pulls `BTN_N` low (internal pull-up).
pub const BUTTON_ACTIVE_LOW: bool = true;
/// DOCKED is the real hall (a leg of the hardware gate), never simulated.
pub const DOCK_SIMULATED: bool = false;
/// Hall output polarity: low = docked.
pub const DOCK_ACTIVE_LOW: bool = true;
/// `MOT_FWD` level for forward.
pub const MOT_FWD_FORWARD_HIGH: bool = true;
/// I2C: 100 kHz (external 4.7 k pull-ups), the TMAG is put to sleep after boot.
pub const I2C_FREQUENCY_HZ: u32 = 100_000;
/// TPL5010 interval (R26 6.8 k): about 2.0 s. Kick timing and the "one watchdog interval" bound use it.
pub const TPL5010_INTERVAL_MS: u32 = 2_000;

/// All pins of the board by function (the SAADC, NVMC and WDT peripherals are taken separately by the caller).
pub struct CupIo {
    /// `VMOT_SENSE` (P0.04, AIN2).
    pub vmot_sense: embassy_nrf::saadc::AnyInput<'static>,
    pub aphase: Peri<'static, AnyPin>,
    pub bphase: Peri<'static, AnyPin>,
    pub aenbl: Peri<'static, AnyPin>,
    pub benbl: Peri<'static, AnyPin>,
    pub chg_stat: Peri<'static, AnyPin>,
    pub oc_ok: Peri<'static, AnyPin>,
    pub latch_q: Peri<'static, AnyPin>,
    pub dock_n: Peri<'static, AnyPin>,
    pub sup_ok: Peri<'static, AnyPin>,
    pub led_r: Peri<'static, AnyPin>,
    pub led_g: Peri<'static, AnyPin>,
    pub led_b: Peri<'static, AnyPin>,
    pub sup_rx: Peri<'static, AnyPin>,
    pub sup_tx: Peri<'static, AnyPin>,
    pub sup_boot0: Peri<'static, AnyPin>,
    pub sup_nrst: Peri<'static, AnyPin>,
    pub mot_fwd: Peri<'static, AnyPin>,
    pub button: Peri<'static, AnyPin>,
    pub i2c_scl: Peri<'static, AnyPin>,
    pub i2c_sda: Peri<'static, AnyPin>,
    pub arm_clk: Peri<'static, AnyPin>,
    pub mcu_en: Peri<'static, AnyPin>,
    pub buz_a: Peri<'static, AnyPin>,
}

/// Moves the board pins out of `$p` (an owned `embassy_nrf::Peripherals`, partial move): the rest of `$p` stays usable, so the
/// pump application can take the board independent peripherals afterwards. `CupIo` must be in scope at the call site.
macro_rules! cup_pins {
    ($p:ident) => {
        CupIo {
            vmot_sense: embassy_nrf::saadc::Input::degrade_saadc($p.P0_04),
            aphase: $p.P1_13.into(),
            bphase: $p.P1_09.into(),
            aenbl: $p.P1_11.into(),
            benbl: $p.P0_26.into(),
            chg_stat: $p.P0_06.into(),
            oc_ok: $p.P0_07.into(),
            latch_q: $p.P1_12.into(),
            dock_n: $p.P0_31.into(),
            sup_ok: $p.P0_28.into(),
            led_r: $p.P0_22.into(),
            led_g: $p.P0_19.into(),
            led_b: $p.P1_00.into(),
            sup_rx: $p.P0_05.into(),
            sup_tx: $p.P0_27.into(),
            sup_boot0: $p.P0_15.into(),
            sup_nrst: $p.P0_12.into(),
            mot_fwd: $p.P0_29.into(),
            button: $p.P0_25.into(),
            i2c_scl: $p.P0_08.into(),
            i2c_sda: $p.P0_11.into(),
            arm_clk: $p.P0_30.into(),
            mcu_en: $p.P0_03.into(),
            buz_a: $p.P1_14.into(),
        }
    };
}
pub(crate) use cup_pins;

/// One-time UICR handling (runs before anything else): `REGOUT0` = 3.3 V, `PSELRESET` = P0.18. The decision is the host tested
/// `openpatch_core::battery::regout0_action`. A fresh module resets once after the write (the new rail voltage needs a reset); a
/// module with another programmed voltage needs `probe-rs erase` once and is NOT started (the rail would be wrong).
pub fn regout0_setup() {
    use embassy_nrf::{uicr_write_masked, WriteResult};
    use openpatch_core::battery::*;
    const PSELRESET0: *mut u32 = 0x1000_1200 as *mut u32;
    const PSELRESET1: *mut u32 = 0x1000_1204 as *mut u32;
    let regout = UICR_REGOUT0_ADDR as *mut u32;
    // SAFETY: fixed UICR registers of the nRF52840; reads and the one-way masked writes of `uicr_write_masked`.
    let word = unsafe { regout.read_volatile() };
    let mut reset = false;
    match regout0_action(word) {
        Regout0Action::Nothing => {}
        Regout0Action::Write => {
            // only bits 2..0 are written (1 -> 0), the upper bits stay as they are
            if let WriteResult::Written = unsafe { uicr_write_masked(regout, REGOUT0_3V3_WORD, REGOUT0_VOUT_MASK) } {
                reset = true;
            }
        }
        Regout0Action::NeedsErase => {
            defmt::error!("UICR.REGOUT0 holds another voltage: erase the UICR once (probe-rs erase); the 3V3 rail is wrong, not starting");
            loop {
                cortex_m::asm::wfi();
            }
        }
    }
    for reg in [PSELRESET0, PSELRESET1] {
        if let WriteResult::Written = unsafe { embassy_nrf::uicr_write(reg, 18) } {
            reset = true;
        }
    }
    if reset {
        defmt::warn!("UICR written (REGOUT0 3.3 V / PSELRESET), resetting once");
        cortex_m::peripheral::SCB::sys_reset();
    }
}
